// WooCommerce signs every webhook delivery: x-wc-webhook-signature is the
// base64 HMAC-SHA256 of the exact request body, keyed with the secret set on
// the webhook in WooCommerce > Settings > Advanced > Webhooks.
//
// The Webhook node runs with Raw Body on, so the bytes WooCommerce signed are
// in binary.data. Re-serialising the parsed JSON would reorder keys and the
// HMAC would never match.
const crypto = require('crypto');

const secret = $env.WOO_WEBHOOK_SECRET;
if (!secret) throw new Error('WOO_WEBHOOK_SECRET is not set on this n8n instance');

const item = $input.first();
const headers = item.json.headers || {};

const rawBody = item.binary?.data?.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body || {});

const presented = String(headers['x-wc-webhook-signature'] || '');
const expected = crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('base64');

const a = Buffer.from(expected, 'utf8');
const b = Buffer.from(presented, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('WooCommerce webhook signature did not match - delivery rejected');
}

const topic = String(headers['x-wc-webhook-topic'] || 'order.updated');
// WooCommerce retries a delivery it did not get a 2xx for, with the same
// delivery id. That id is what makes this pipeline safe to retry.
const deliveryId = String(headers['x-wc-webhook-delivery-id'] || headers['x-wc-webhook-id'] || '');
if (!deliveryId) throw new Error('WooCommerce delivery has no id - cannot deduplicate it');

const order = JSON.parse(rawBody);
if (!order.id) throw new Error('Webhook body is not an order');

return [
  {
    json: {
      delivery_id: deliveryId,
      topic,
      order_id: order.id,
      order_number: String(order.number || order.id),
      status: String(order.status || 'pending'),
      currency: order.currency || $env.STORE_CURRENCY || 'GBP',
      total: Number(order.total || 0),
      date_created: order.date_created || null,
      payment_method_title: order.payment_method_title || null,
      payment_url: order.payment_url || null,
      customer_id: order.customer_id || 0,
      customer_email: String(order.billing?.email || '').trim().toLowerCase(),
      customer_name: [order.billing?.first_name, order.billing?.last_name].filter(Boolean).join(' '),
      line_items: (order.line_items || []).map((li) => ({
        product_id: li.product_id,
        name: li.name,
        quantity: li.quantity,
        total: Number(li.total || 0),
      })),
    },
  },
];

// Reached from the error output of the history lookup. The order still
// has to be handled, so one marker item is emitted and Enrich Customer
// treats the customer as unknown rather than as new. Dropping the order
// here would be the silent failure this whole design exists to avoid.
return [{ json: { history_unavailable: true } }];

// Two numbers decide everything downstream: how much this customer is worth,
// and whether this is their first order. Both come from the store, not from a
// CRM that may be a day behind.
const order = $('Verify Woo Signature').first().json;
const input = $input.all().map((i) => i.json);

// Set by "No History Available" when the store's order list could not be read.
// A first-time buyer legitimately has an empty history; a failed read does not,
// and the two must not be confused.
const degraded = input.some((o) => o && o.history_unavailable);
const history = input.flatMap((o) => (Array.isArray(o?.body) ? o.body : [])).filter((o) => o && o.id);

// The current order can already be in the history response. Counting it twice
// would turn a first-time buyer into a returning one on their very first order.
const previous = history.filter((o) => String(o.id) !== String(order.order_id));

const paid = previous.filter((o) => ['completed', 'processing'].includes(o.status));
const lifetimeValue = paid.reduce((sum, o) => sum + Number(o.total || 0), 0);
const orderCount = paid.length;

const dates = paid.map((o) => new Date(o.date_created).getTime()).filter((t) => !Number.isNaN(t));
const firstOrderAt = dates.length ? new Date(Math.min(...dates)).toISOString() : null;

const threshold = Number($env.HIGH_VALUE_ORDER_THRESHOLD || 150);
const vipThreshold = Number($env.VIP_LIFETIME_VALUE_THRESHOLD || 500);

// Degraded read: an unknown customer is not the same as a new one. Welcoming
// somebody who has shopped here for three years is worse than not welcoming a
// genuine new customer, so on a failed history read nobody gets welcomed.
const firstTimeBuyer = !degraded && orderCount === 0;
const recoverable = ['pending', 'failed', 'on-hold'].includes(order.status);

return [
  {
    json: {
      ...order,
      lifetime_value: Number(lifetimeValue.toFixed(2)),
      lifetime_value_incl_this: Number((lifetimeValue + order.total).toFixed(2)),
      previous_order_count: orderCount,
      average_order_value: orderCount ? Number((lifetimeValue / orderCount).toFixed(2)) : null,
      first_order_at: firstOrderAt,
      first_time_buyer: firstTimeBuyer,
      high_value: order.total >= threshold || (!degraded && lifetimeValue + order.total >= vipThreshold),
      payment_recoverable: recoverable,
      segment: degraded ? 'unknown' : firstTimeBuyer ? 'new' : lifetimeValue >= vipThreshold ? 'vip' : 'returning',
      history_degraded: degraded,
      high_value_threshold: threshold,
    },
  },
];

const c = $json;
return [
  {
    json: {
      ...c,
      slack_payload: {
        text: 'High-value order ' + c.order_number + ' - ' + c.currency + ' ' + c.total.toFixed(2),
        blocks: [
          { type: 'header', text: { type: 'plain_text', text: 'High-value order #' + c.order_number } },
          {
            type: 'section',
            fields: [
              { type: 'mrkdwn', text: '*Value*\n' + c.currency + ' ' + c.total.toFixed(2) },
              { type: 'mrkdwn', text: '*Customer*\n' + (c.customer_name || c.customer_email) },
              { type: 'mrkdwn', text: '*Segment*\n' + c.segment },
              { type: 'mrkdwn', text: '*Lifetime value*\n' + c.currency + ' ' + c.lifetime_value_incl_this.toFixed(2) },
            ],
          },
          {
            type: 'section',
            text: {
              type: 'mrkdwn',
              text: '*Items*\n' + c.line_items.map((li) => '- ' + li.quantity + ' x ' + li.name).join('\n'),
            },
          },
        ],
      },
    },
  },
];

// Every branch ends here, success or failure, so the actions table is a
// complete record of what the automation did to each order - including the
// times it tried and could not.
const ctx = $('Enrich Customer').first().json;
const result = $input.first().json;
const failed = Boolean(result?.error);

// Which branch called us. $prevNode is the node that produced this item.
const source = $prevNode.name;
const ACTION_BY_NODE = {
  'Alert Sales Channel': 'high_value_alert',
  'Start Welcome Sequence': 'welcome_sequence',
  'Send Payment Recovery Nudge': 'payment_recovery_nudge',
  'No Action Needed': 'none',
};

return [
  {
    json: {
      delivery_id: ctx.delivery_id,
      order_id: ctx.order_id,
      order_number: ctx.order_number,
      customer_email: ctx.customer_email,
      segment: ctx.segment,
      lifetime_value: ctx.lifetime_value_incl_this,
      order_total: ctx.total,
      order_status: ctx.status,
      action: ACTION_BY_NODE[source] || source,
      succeeded: !failed,
      detail: failed
        ? String(result?.error?.message || result?.error || 'unknown failure').slice(0, 500)
        : null,
      execution_id: $execution.id,
    },
  },
];
